nodes.Process Population Data:
const allItems = $input.all();
const nomisRaw = allItems[0].json.data;
const supplementRaw = allItems[1].json.data;

// Parse CSV helper
function parseCSV(text) {
  const lines = text.trim().split('\n');
  const headers = lines[0].replace(/"/g, '').split(',');
  return lines.slice(1).map(line => {
    const vals = line.replace(/"/g, '').split(',');
    const obj = {};
    headers.forEach((h, i) => obj[h.trim()] = (vals[i] || '').trim());
    return obj;
  });
}

// Parse Nomis - filter English LAs with values only
const nomisRows = parseCSV(nomisRaw)
  .filter(r => r.GEOGRAPHY_CODE && r.GEOGRAPHY_CODE.startsWith('E') && r.OBS_VALUE && r.OBS_VALUE !== '')
  .map(r => ({
    lad24cd: r.GEOGRAPHY_CODE,
    la_name: r.GEOGRAPHY_NAME,
    population: parseInt(r.OBS_VALUE),
    reference_year: parseInt(r.DATE_NAME)
  }));

// Parse supplement
const supplementRows = parseCSV(supplementRaw)
  .map(r => ({
    lad24cd: r.lad24cd,
    la_name: r.la_name,
    population: parseInt(r.population),
    reference_year: parseInt(r.reference_year)
  }));

// Merge - supplement takes precedence
const nomisMap = {};
nomisRows.forEach(r => nomisMap[r.lad24cd] = r);
supplementRows.forEach(r => nomisMap[r.lad24cd] = r);

const merged = Object.values(nomisMap);

return [{
  json: {
    rows: merged,
    row_count: merged.length,
    nomis_count: nomisRows.length,
    supplement_count: supplementRows.length,
    batch_json: JSON.stringify(merged)
  }
}];

