nodes.Parse VOA Response:
const lad24cd  = $input.item.json.lad24cd;
const lad24nm  = $input.item.json.lad24nm;
const postcode = $input.item.json.postcode;
const html     = $input.item.json.data ?? $input.item.json.body ?? '';

if (!html || typeof html !== 'string') {
  return [{ json: { lad24cd, lad24nm, postcode, lha: null, error: 'Empty response from VOA' } }];
}

const now   = new Date();
const month = now.getMonth() + 1;
const year  = now.getFullYear();

// BRMA name
const brmaMatch = html.match(/###?\s*([^\n]+?)\s*BRMA/i);
const brma_name = brmaMatch ? brmaMatch[1].trim() : null;

// Parse weekly rates
const parseRate = (label) => {
  const pattern = new RegExp(label + '[^£]*£([\\d,.]+)\\s*per week', 'i');
  const match = html.match(pattern);
  return match ? parseFloat(match[1].replace(/,/g, '')) : null;
};

const weekly = {
  shared:    parseRate('Shared Accommodation Rate'),
  one_bed:   parseRate('One Bedroom Rate'),
  two_bed:   parseRate('Two Bedrooms Rate'),
  three_bed: parseRate('Three Bedrooms Rate'),
  four_bed:  parseRate('Four Bedrooms Rate'),
};

const toMonthly = (w) => w ? Math.round((w * 52) / 12) : null;
const monthly = {
  shared:    toMonthly(weekly.shared),
  one_bed:   toMonthly(weekly.one_bed),
  two_bed:   toMonthly(weekly.two_bed),
  three_bed: toMonthly(weekly.three_bed),
  four_bed:  toMonthly(weekly.four_bed),
};

const hasData = Object.values(weekly).some(v => v !== null);

if (!hasData) {
  return [{ json: { lad24cd, lad24nm, postcode, lha: null, brma_name, error: 'Could not parse rates — VOA page structure may have changed' } }];
}

return [{
  json: {
    lad24cd,
    lad24nm,
    postcode,
    brma_name,
    rate_period:       `${String(month).padStart(2,'0')}/${year}`,
    lha_shared_weekly:    weekly.shared,
    lha_one_bed_weekly:   weekly.one_bed,
    lha_two_bed_weekly:   weekly.two_bed,
    lha_three_bed_weekly: weekly.three_bed,
    lha_four_bed_weekly:  weekly.four_bed,
    lha_shared_monthly:   monthly.shared,
    lha_one_bed_monthly:  monthly.one_bed,
    lha_two_bed_monthly:  monthly.two_bed,
    lha_three_bed_monthly: monthly.three_bed,
    lha_four_bed_monthly: monthly.four_bed,
    parse_error: null,
    retrieved_at: now.toISOString(),
  }
}];
